'use client';

import * as React from 'react';
import { Well } from '../well/well';
import { Kbd } from '../kbd/kbd';
import './field.css';

/* FIELD: text input in a well, a leading glyph and trailing keycaps (the palette's field).
 * SEARCH FIELD: a button in a well that opens search (the dock's search well), light or graphite.
 * Field slots: Field.Root, Field.Icon, Field.Input, Field.Trail. */

const Root = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement> & { tone?: 'light' | 'graphite' }>(function FieldRoot({ tone = 'light', className, ...props }, ref) {
  return <Well ref={ref} as="label" variant={tone === 'graphite' ? 'graphite' : 'field'} className={className ? `mu-field ${className}` : 'mu-field'} {...props} />;
});
function Icon({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span aria-hidden className={className ? `mu-field-icon ${className}` : 'mu-field-icon'} {...props} />;
}
const Input = React.forwardRef<HTMLInputElement, React.InputHTMLAttributes<HTMLInputElement>>(function FieldInput({ className, ...props }, ref) {
  return <input ref={ref} autoComplete="off" spellCheck={false} className={className ? `mu-field-input ${className}` : 'mu-field-input'} {...props} />;
});
function Trail({ className, ...props }: React.HTMLAttributes<HTMLSpanElement>) {
  return <span className={className ? `mu-field-trail ${className}` : 'mu-field-trail'} {...props} />;
}

export const Field = Object.assign(Root, { Root, Icon, Input, Trail });

export interface SearchFieldProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'children'> {
  /** What the well says: "Lens or action". */
  placeholder: string;
  icon?: React.ReactNode;
  /** The key that opens it (a keycap at the end): "⌘K". */
  shortcut?: string;
  tone?: 'light' | 'graphite';
}

/** A button in a well that opens search. */
export const SearchField = React.forwardRef<HTMLButtonElement, SearchFieldProps>(function SearchField({ placeholder, icon, shortcut = '⌘K', tone = 'graphite', className, type = 'button', ...props }, ref) {
  return (
    <button ref={ref} type={type} data-tone={tone} aria-keyshortcuts={shortcut === '⌘K' ? 'Meta+K' : undefined} className={className ? `mu-search-field ${className}` : 'mu-search-field'} {...props}>
      {icon && <span aria-hidden className="mu-field-icon">{icon}</span>}
      <span className="mu-search-field-text">{placeholder}</span>
      {shortcut && <Kbd surface={tone === 'graphite' ? 'strip' : 'default'} size="default">{shortcut}</Kbd>}
    </button>
  );
});

@import "../tokens.css";
@import "../kbd/kbd.css";

/* Field and search field. Their look is the field recipe (--mu-r-field-*) on the well. */
.mu-field {
  display: flex;
  align-items: center;
  gap: var(--mu-r-field-field-gap);
  height: var(--mu-r-field-field-height);
  padding: var(--mu-zero) var(--mu-r-field-field-pad-right) var(--mu-zero) var(--mu-r-field-field-pad-left);
  border-radius: var(--mu-r-field-field-radius);
  color: var(--mu-r-field-field-hint);
  cursor: text;
}
.mu-field-icon { display: inline-grid; flex: none; }
.mu-field > .mu-field-icon > svg { width: var(--mu-r-field-field-glyph); height: var(--mu-r-field-field-glyph); }
.mu-field-input {
  flex: 1;
  min-width: var(--mu-zero);
  padding: var(--mu-zero);
  border: var(--mu-zero);
  outline: var(--mu-zero);
  background: transparent;
  font: var(--mu-r-field-field-font);
  letter-spacing: var(--mu-r-field-field-tracking);
  color: var(--mu-r-field-field-ink);
  caret-color: var(--mu-r-field-field-caret);
}
.mu-field-input::placeholder { color: var(--mu-r-field-field-hint); }
.mu-field-input:focus-visible { outline: none; }
.mu-field-trail { display: inline-flex; align-items: center; margin-left: auto; }

.mu-search-field {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--mu-r-field-search-gap);
  height: var(--mu-r-field-search-height);
  min-width: var(--mu-r-field-search-min-width);
  padding: var(--mu-zero) var(--mu-r-field-search-pad-right) var(--mu-zero) var(--mu-r-field-search-pad-left);
  border: var(--mu-zero);
  border-radius: var(--mu-r-field-search-radius);
  font: var(--mu-r-field-search-font);
  letter-spacing: var(--mu-r-field-search-tracking);
  cursor: text;
}
.mu-search-field[data-tone="graphite"] { color: var(--mu-r-field-search-ink); background: var(--mu-r-well-self-graphite-background); box-shadow: var(--mu-r-well-self-graphite-shadow); }
.mu-search-field[data-tone="light"] { color: var(--mu-r-field-field-hint); background: var(--mu-r-well-self-field-background); box-shadow: var(--mu-r-well-self-field-shadow); }
.mu-search-field > .mu-field-icon > svg { width: var(--mu-r-field-search-glyph); height: var(--mu-r-field-search-glyph); }
.mu-search-field > .mu-kbd { margin-left: auto; }
.mu-search-field:focus-visible { outline: var(--mu-focus-width) solid var(--mu-focus); outline-offset: var(--mu-zero); }
